<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div class="content"><div class="panel_s"><div class="panel-body"><h4><i class="fa fa-undo"></i> مرجوعی کالا</h4><p class="text-muted">فقط فاکتورهایی که تحویل مشتری شده‌اند قابل مرجوعی هستند. مرجوعی می‌تواند جزئی یا کامل و در چند نوبت انجام شود.</p><hr><h4>مرجوعی‌های تاریخی (بدون اثر مالی و انباری)</h4><p class="text-muted">سوابق واردشده از فاکتورهای قدیمی؛ به فاکتور تحویل‌شده فعلی وابسته نیستند.</p><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>شماره فاکتور تاریخی</th><th>تاریخ</th><th>شناسه مشتری</th><th>مبلغ مرجوعی</th><th>تاریخ ثبت</th></tr></thead><tbody><?php foreach(($historical_returns??[]) as $hr): ?><tr><td><?= html_escape($hr['invoice_key']) ?></td><td><?= html_escape($hr['invoice_date']) ?></td><td><?= (int)$hr['customer_id'] ?></td><td><?= app_format_money($hr['total_amount'],'') ?></td><td><?= html_escape($hr['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><hr><h4>مرجوعی فاکتورهای جاری</h4><table class="table dt-table"><thead><tr><th>فاکتور</th><th>مشتری</th><th>مبلغ</th><th>وضعیت مالی</th><th>وضعیت مرجوعی</th><th>اعتبار مرجوعی</th><th>عملیات</th></tr></thead><tbody><?php foreach($invoices as $i){?><tr><td><?php echo html_escape($i['number']);?></td><td><?php echo html_escape($i['company']?:'-');?></td><td><?php echo app_format_money($i['total'],'');?></td><td><?php echo html_escape($i['payment_state']);?></td><td><?php echo html_escape($i['return_state']??'بدون مرجوعی');?><?php if(!empty($i['return_count'])) echo ' ('.(int)$i['return_count'].' سند)';?></td><td><?php $fs=$this->sdf->return_financial_summary($i['id']); echo app_format_money($fs['return_credit']??0,'');?></td><td><a class="btn btn-primary btn-sm" href="<?php echo admin_url('sales_delivery_flow/return_invoice/'.$i['id']);?>"><i class="fa fa-undo"></i> ثبت / مدیریت مرجوعی</a></td></tr><?php }?></tbody></table></div></div></div></div><?php init_tail(); ?>
